// Compile the existing pure shared calculations for the Node Functions deployment.
const fs = require("node:fs");
const path = require("node:path");
const ts = require("typescript");
const root = path.resolve(__dirname, "..");
const seen = new Set();
function compile(name) {
  if (seen.has(name)) return;
  seen.add(name);
  const source = fs.readFileSync(
    path.join(root, "shared", `${name}.ts`),
    "utf8",
  );
  for (const match of source.matchAll(/from ['"]\.\/([^'"]+)['"]/g))
    compile(match[1].replace(/\.ts$/, ""));
  const output =
    "// Generated by scripts/sync-orson-domain.cjs; edit shared source.\n" +
    ts
      .transpileModule(source, {
        compilerOptions: {
          target: ts.ScriptTarget.ES2022,
          module: ts.ModuleKind.CommonJS,
        },
      })
      .outputText.replace(/require\("\.\/([^"\n]+)\.ts"\)/g, 'require("./$1")');
  const destination = path.join(
    root,
    "functions/shared/orsonDomain",
    `${name}.js`,
  );
  if (process.argv.includes("--check")) {
    if (
      !fs.existsSync(destination) ||
      fs.readFileSync(destination, "utf8") !== output
    )
      throw new Error(`Stale Orson domain mirror: ${name}`);
  } else fs.writeFileSync(destination, output);
}
[
  "dailyFeedTransaction",
  "feedInventoryUsage",
  "financeSync",
  "harvestCalculations",
  "physicalPondIdentity",
  "enterpriseCycles",
  "orsonAgentContract",
  "orsonEvidence",
].forEach(compile);
console.log(
  `Orson shared domain mirrors ${process.argv.includes("--check") ? "verified" : "updated"} (${seen.size}).`,
);
